ALTER TABLE organizations ADD COLUMN about_short JSON NULL AFTER description;

UPDATE organizations
SET about_short = CASE id
  WHEN 'ache' THEN JSON_OBJECT('pt', 'O Aché é um laboratório farmacêutico brasileiro que pesquisa, desenvolve e fabrica medicamentos.', 'en', 'Aché is a Brazilian pharmaceutical company that researches, develops and manufactures medicines.')
  WHEN 'aptah' THEN JSON_OBJECT('pt', 'A Aptah Bio é uma empresa de biotecnologia que desenvolve terapias baseadas em DNA, com foco em oncologia.', 'en', 'Aptah Bio is a biotechnology company developing DNA-based therapies with a focus on oncology.')
  WHEN 'biomanguinhos' THEN JSON_OBJECT('pt', 'Bio-Manguinhos é a unidade da Fiocruz dedicada à pesquisa, ao desenvolvimento e à produção de imunobiológicos para a saúde pública.', 'en', 'Bio-Manguinhos is the Fiocruz unit that researches, develops and produces immunobiological products for public health.')
  WHEN 'biocase' THEN JSON_OBJECT('pt', 'A Biocase Group desenvolve soluções terapêuticas para saúde mental, com foco em transtornos psiquiátricos e dependência.', 'en', 'Biocase Group develops therapies for mental health, with a focus on psychiatric disorders and addiction.')
  WHEN 'biolinker' THEN JSON_OBJECT('pt', 'A BioLinker desenvolve tecnologias de bioprocessos para a produção de proteínas e a pesquisa em biotecnologia.', 'en', 'BioLinker develops bioprocess technologies for protein production and biotechnology research.')
  WHEN 'bionovis' THEN JSON_OBJECT('pt', 'A Bionovis desenvolve e fabrica medicamentos biológicos e oferece serviços de produção biofarmacêutica.', 'en', 'Bionovis develops and manufactures biological medicines and provides biopharmaceutical manufacturing services.')
  WHEN 'bluetouch40' THEN JSON_OBJECT('pt', 'A Bluetouch40+ atua em saúde digital, com foco na integração de dados clínicos e na prevenção e no diagnóstico precoce em saúde masculina.', 'en', 'Bluetouch40+ works in digital health, focusing on clinical data integration, prevention and early detection in men''s health.')
  WHEN 'cellertz' THEN JSON_OBJECT('pt', 'A Cellertz Bio é uma empresa de biotecnologia que usa inteligência artificial para desenvolver terapias de mRNA para oncologia.', 'en', 'Cellertz Bio is a biotechnology company that uses artificial intelligence to develop mRNA therapies for oncology.')
  WHEN 'celluris' THEN JSON_OBJECT('pt', 'A Celluris desenvolve terapias celulares para oncologia, com foco em tecnologias CAR-T para tumores sólidos.', 'en', 'Celluris develops cell therapies for oncology, focusing on CAR-T technologies for solid tumors.')
  WHEN 'cristalia' THEN JSON_OBJECT('pt', 'O Cristália é um laboratório farmacêutico brasileiro que pesquisa, desenvolve e fabrica medicamentos.', 'en', 'Cristália is a Brazilian pharmaceutical company that researches, develops and manufactures medicines.')
  WHEN 'croplabs' THEN JSON_OBJECT('pt', 'A Crop Labs é uma organização de pesquisa contratada (CRO) que realiza ensaios pré-clínicos e controle de qualidade.', 'en', 'Crop Labs is a contract research organization (CRO) that performs preclinical testing and quality control.')
  WHEN 'embrapa' THEN JSON_OBJECT('pt', 'A Embrapa é uma instituição pública brasileira de pesquisa agropecuária que desenvolve e licencia tecnologias para o setor.', 'en', 'Embrapa is a Brazilian public agricultural research institution that develops and licenses technologies for the sector.')
  WHEN 'emunah' THEN JSON_OBJECT('pt', 'A Emunah atua em pesquisa e desenvolvimento em biotecnologia, com foco em saúde e cuidados com a pele.', 'en', 'Emunah conducts biotechnology research and development, with a focus on health and skin care.')
  WHEN 'futrbio' THEN JSON_OBJECT('pt', 'A FUTR Bio é uma empresa de biotecnologia dedicada à pesquisa e ao desenvolvimento de vacinas de mRNA.', 'en', 'FUTR Bio is a biotechnology company dedicated to mRNA vaccine research and development.')
  WHEN 'centroflora' THEN JSON_OBJECT('pt', 'O Grupo Centroflora pesquisa e desenvolve ingredientes botânicos brasileiros para os setores nutracêutico e farmacêutico.', 'en', 'Grupo Centroflora researches and develops Brazilian botanical ingredients for the nutraceutical and pharmaceutical sectors.')
  WHEN 'heptech' THEN JSON_OBJECT('pt', 'A Heptech é uma empresa de biotecnologia focada no desenvolvimento de insumos farmacêuticos para anticoagulação.', 'en', 'Heptech is a biotechnology company focused on developing pharmaceutical ingredients for anticoagulation.')
  WHEN 'huna' THEN JSON_OBJECT('pt', 'A Huna aplica inteligência artificial a dados clínicos para apoiar o rastreamento e a detecção precoce de câncer.', 'en', 'Huna applies artificial intelligence to clinical data to support cancer screening and early detection.')
  WHEN 'imunotera' THEN JSON_OBJECT('pt', 'A ImunoTera desenvolve imunoterapias para oncologia e doenças virais emergentes.', 'en', 'ImunoTera develops immunotherapies for oncology and emerging viral diseases.')
  WHEN 'butantan' THEN JSON_OBJECT('pt', 'O Instituto Butantan é uma instituição pública brasileira de pesquisa, desenvolvimento e produção de imunobiológicos.', 'en', 'Instituto Butantan is a Brazilian public institution that researches, develops and produces immunobiological products.')
  WHEN 'ionvet' THEN JSON_OBJECT('pt', 'A IonVet é uma organização de pesquisa contratada (CRO) que presta serviços analíticos e de pesquisa para saúde animal e agronegócio.', 'en', 'IonVet is a contract research organization (CRO) providing analytical and research services for animal health and agribusiness.')
  WHEN 'kimera' THEN JSON_OBJECT('pt', 'A Kimera Biotecnologia desenvolve soluções biotecnológicas para reprodução animal.', 'en', 'Kimera Biotecnologia develops biotechnology solutions for animal reproduction.')
  WHEN 'krabs' THEN JSON_OBJECT('pt', 'A KRABS é uma empresa de biotecnologia que pesquisa e desenvolve anticorpos para aplicações em saúde e diagnóstico.', 'en', 'KRABS is a biotechnology company that researches and develops antibodies for health and diagnostic applications.')
  WHEN 'microforge' THEN JSON_OBJECT('pt', 'A Micro Forge é uma empresa brasileira de biotecnologia industrial que desenvolve processos fermentativos para produzir moléculas de alto valor.', 'en', 'Micro Forge is a Brazilian industrial biotechnology company that develops fermentation processes to produce high-value molecules.')
  WHEN 'mirscience' THEN JSON_OBJECT('pt', 'A Mirscience Therapeutics desenvolve terapias baseadas em RNA com foco em doenças musculares.', 'en', 'Mirscience Therapeutics develops RNA-based therapies focused on muscle disorders.')
  WHEN 'nintx' THEN JSON_OBJECT('pt', 'A Nintx desenvolve terapias de origem natural e aplica inteligência artificial à pesquisa do microbioma.', 'en', 'Nintx develops naturally derived therapies and applies artificial intelligence to microbiome research.')
  WHEN 'peptidus' THEN JSON_OBJECT('pt', 'A Peptidus Biotech usa inteligência artificial para pesquisar e desenvolver peptídeos terapêuticos para saúde animal.', 'en', 'Peptidus Biotech uses artificial intelligence to research and develop therapeutic peptides for animal health.')
  WHEN 'qnity' THEN JSON_OBJECT('pt', 'A Qnity desenvolve instrumentação científica baseada em eletroquímica quântica para pesquisa e análise molecular.', 'en', 'Qnity develops scientific instrumentation based on quantum electrochemistry for research and molecular analysis.')
  WHEN 'sante' THEN JSON_OBJECT('pt', 'A Sante Science desenvolve ingredientes bioativos por fermentação microbiana, com foco em saúde animal.', 'en', 'Sante Science develops bioactive ingredients through microbial fermentation, with a focus on animal health.')
  WHEN 'techtrials' THEN JSON_OBJECT('pt', 'A Techtrials transforma dados de saúde em evidências para apoiar decisões da indústria farmacêutica, de hospitais, operadoras e da pesquisa clínica.', 'en', 'Techtrials turns health data into evidence to support decisions across pharma, hospitals, health insurers and clinical research.')
  WHEN 'vesper' THEN JSON_OBJECT('pt', 'A Vesper Biotechnologies cria e investe em empresas brasileiras de biotecnologia para agricultura sustentável e saúde humana.', 'en', 'Vesper Biotechnologies builds and invests in Brazilian biotechnology companies for sustainable agriculture and human health.')
  WHEN 'vyro' THEN JSON_OBJECT('pt', 'A VYRO Biotherapeutics desenvolve tecnologias de entrega gênica e terapias para oncologia.', 'en', 'VYRO Biotherapeutics develops gene delivery technologies and therapies for oncology.')
  WHEN 'wecare' THEN JSON_OBJECT('pt', 'A Wecare Skin desenvolve tratamentos dermatológicos com foco em doenças inflamatórias da pele.', 'en', 'Wecare Skin develops dermatological treatments focused on inflammatory skin conditions.')
END
WHERE about_short IS NULL AND id IN (
  'ache', 'aptah', 'biomanguinhos', 'biocase', 'biolinker', 'bionovis', 'bluetouch40', 'cellertz', 'celluris', 'cristalia', 'croplabs', 'embrapa', 'emunah', 'futrbio', 'centroflora', 'heptech', 'huna', 'imunotera', 'butantan', 'ionvet', 'kimera', 'krabs', 'microforge', 'mirscience', 'nintx', 'peptidus', 'qnity', 'sante', 'techtrials', 'vesper', 'vyro', 'wecare'
);
